1	package calibrate
2	
3	import (
4		"errors"
5		"math"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// TestFailedRegisterSaveLeavesNoInstrument 覆盖核心修复：登记内容合法但台账文件
13	// 无法写入或替换时明确报保存错误——失败的新器具不出现在列表、不占用编号，
14	// 不能被安排校准或申请使用，也不会被随后其他成功保存的操作顺带写入。恢复可写后
15	// 无需重新打开台账，重新提交且保存成功才新增一件待校准器具，登记时间、名称与
16	// 允许误差取本次成功提交；此前已保存器具的状态、证书、计划与使用记录不受影响。
17	func TestFailedRegisterSaveLeavesNoInstrument(t *testing.T) {
18		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
19		path := filepath.Join(t.TempDir(), "ledger.json")
20		l, err := openAt(path, clock.now)
21		if err != nil {
22			t.Fatalf("open: %v", err)
23		}
24		mustRegister(t, l, "M-1", "万用表", 0.5)
25		mustRegister(t, l, "M-2", "示波器", 1.0)
26		// M-1 上准备好证书、状态、使用留痕与校准计划，失败登记不得影响它们。
27		mustAddCert(t, l, CertificateInput{
28			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
29			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
30		})
31		if err := l.SetStatus("M-1", StatusInUse); err != nil {
32			t.Fatalf("set in-use: %v", err)
33		}
34		allowedUse, err := l.RequestUse("M-1")
35		if err != nil || !allowedUse.Allowed {
36			t.Fatalf("M-1 应可获准使用：err=%v decision=%v", err, allowedUse)
37		}
38		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1",
39			Date: "2026-10-10", Note: "周期校准"})
40	
41		// 失败申请：10-03 提交，名称与误差是这份内容；恢复后将用不同内容重新提交，
42		// 证明成功提交不会沿用失败申请。
43		clock.t = mustDate(t, "2026-10-03")
44		failed := RegisterInput{ID: "M-NEW", Name: "失败名称", AllowedError: 0.25}
45		blockSaving(t, l)
46		inst, err := l.Register(failed)
47		if err == nil {
48			t.Fatal("台账文件无法替换时必须返回保存错误")
49		}
50		if inst != nil {
51			t.Fatalf("保存失败不能返回已登记的器具：%+v", inst)
52		}
53		if IsValidation(err) || errors.Is(err, ErrNotFound) {
54			t.Fatalf("写盘失败应是保存错误而非业务拒绝：%v", err)
55		}
56		if !strings.Contains(err.Error(), path) {
57			t.Fatalf("保存错误应指出台账文件 %s：%v", path, err)
58		}
59	
60		// 文件仍不可写时再次提交同号合法内容：仍报保存错误，不能被内存中残留的
61		// 失败器具当成“编号重复”业务拒绝。
62		if inst2, err := l.Register(failed); err == nil || inst2 != nil {
63			t.Fatalf("再次提交应仍报保存失败：err=%v inst=%v", err, inst2)
64		} else if IsValidation(err) {
65			t.Fatalf("再次提交不得被当成编号重复而业务拒绝：%v", err)
66		}
67	
68		// 文件不可写时，原本不合法的申请仍报原有业务或参数错误，不触碰写盘。
69		bad := []RegisterInput{
70			{ID: "   ", Name: "x", AllowedError: 1},
71			{ID: "M-X", Name: "\t", AllowedError: 1},
72			{ID: "M-X", Name: "x", AllowedError: -0.01},
73			{ID: "M-X", Name: "x", AllowedError: math.NaN()},
74			{ID: "M-X", Name: "x", AllowedError: math.Inf(1)},
75			// 已经保存的编号不能覆盖：即使写盘被挡住，也按业务校验拒绝。
76			{ID: " M-1 ", Name: "覆盖者", AllowedError: 9},
77		}
78		for i, in := range bad {
79			if got, err := l.Register(in); err == nil || got != nil {
80				t.Fatalf("非法用例 %d 应被拒绝且不返回器具：err=%v inst=%v", i, err, got)
81			} else if !IsValidation(err) {
82				t.Fatalf("非法用例 %d 应报业务校验错误而非文件错误：%v", i, err)
83			}
84		}
85		// 零误差的合法登记仍会走到写盘并报保存错误（不是业务拒绝）。
86		if got, err := l.Register(RegisterInput{ID: "M-ZERO", Name: "零限", AllowedError: 0}); err == nil || got != nil {
87			t.Fatalf("零误差合法申请应走到保存并报保存错误：err=%v inst=%v", err, got)
88		} else if IsValidation(err) {
89			t.Fatalf("零误差是合法登记，不应被业务拒绝：%v", err)
90		}
91	
92		// 继续使用同一台账对象（无需重开）：各入口都看不到失败器具，列表与登记前一致。
93		if l.findInstrument("M-NEW") != nil || l.findInstrument("M-ZERO") != nil {
94			t.Fatalf("失败器具留在了台账中：%+v", l.data.Instruments)
95		}
96		if listed := l.Instruments(); len(listed) != 2 ||
97			listed[0].ID != "M-1" || listed[1].ID != "M-2" {
98			t.Fatalf("列表应与登记前一致（只有 M-1、M-2）：%+v", listed)
99		}
100		if _, err := l.Review("M-NEW"); !errors.Is(err, ErrNotFound) {
101			t.Fatalf("按失败编号核对应报告器具不存在：%v", err)
102		}
103		if _, err := l.CanUse("M-NEW"); !errors.Is(err, ErrNotFound) {
104			t.Fatalf("失败器具不能参与使用资格判断：%v", err)
105		}
106		if _, err := l.RequestUse("M-NEW"); !errors.Is(err, ErrNotFound) {
107			t.Fatalf("失败器具不能申请使用：%v", err)
108		}
109		if _, _, err := l.AddCertificate(CertificateInput{
110			InstrumentID: "M-NEW", Number: "C-X", CalDate: "2026-10-02",
111			Expiry: "2027-10-02", Method: "m", Error: 0, Summary: "s",
112		}); !errors.Is(err, ErrNotFound) {
113			t.Fatalf("不能给失败器具录入证书：%v", err)
114		}
115		if _, err := l.CreatePlan(PlanInput{Number: "P-X", InstrumentID: "M-NEW",
116			Date: "2026-10-10", Note: "x"}); !errors.Is(err, ErrNotFound) {
117			t.Fatalf("不能为失败器具安排校准计划：%v", err)
118		}
119	
120		// 此前已保存器具的状态、证书、计划与使用记录保持原样。
121		if got := l.findInstrument("M-1"); got.Status != StatusInUse ||
122			got.Name != "万用表" || got.AllowedError != 0.5 {
123			t.Fatalf("失败登记改动了原有器具：%+v", got)
124		}
125		if c := l.findCertificate("C-1"); c == nil {
126			t.Fatal("原有证书丢失")
127		}
128		if p := l.findPlan("P-1"); p == nil {
129			t.Fatal("原有计划丢失")
130		}
131		if recs := l.UsageRecords(); len(recs) != 1 || recs[0].InstrumentID != "M-1" {
132			t.Fatalf("原有使用记录被改动：%+v", recs)
133		}
134	
135		// 恢复可写后不必重开台账：先对原有器具完成一次正常的状态切换，失败器具
136		// 不能被顺带写入文件。
137		restoreSaving(t, l)
138		if err := l.SetStatus("M-1", StatusRetired); err != nil {
139			t.Fatalf("恢复后正常操作应能保存: %v", err)
140		}
141		raw, err := os.ReadFile(path)
142		if err != nil {
143			t.Fatalf("读取台账文件: %v", err)
144		}
145		if strings.Contains(string(raw), "M-NEW") || strings.Contains(string(raw), "M-ZERO") ||
146			strings.Contains(string(raw), "失败名称") {
147			t.Fatalf("失败器具被随后成功的写盘顺带写入文件：\n%s", raw)
148		}
149		reopened, err := openAt(path, clock.now)
150		if err != nil {
151			t.Fatalf("reopen: %v", err)
152		}
153		if reopened.findInstrument("M-NEW") != nil {
154			t.Fatalf("文件中不应出现失败器具：%+v", reopened.data.Instruments)
155		}
156	
157		// 在同一台账对象重新提交该编号：时间推进到 10-05，名称与允许误差也改用新
158		// 内容。只有这次保存成功才新增器具，登记时间、名称与误差取本次提交。
159		clock.t = mustDate(t, "2026-10-05")
160		success := RegisterInput{ID: " M-NEW ", Name: " 成功名称 ", AllowedError: 0.75}
161		ok, err := l.Register(success)
162		if err != nil || ok == nil {
163			t.Fatalf("恢复后重新提交应成功登记：err=%v inst=%v", err, ok)
164		}
165		if ok.ID != "M-NEW" || ok.Name != "成功名称" || ok.AllowedError != 0.75 {
166			t.Fatalf("成功登记的编号/名称/误差应取本次提交并裁剪空白：%+v", ok)
167		}
168		if ok.Status != StatusPending {
169			t.Fatalf("新登记器具应为待校准状态：%s", ok.Status)
170		}
171		if ok.RegisteredAt != "2026-10-05T00:00:00Z" {
172			t.Fatalf("登记时间应取本次成功提交的时间，得到 %s", ok.RegisteredAt)
173		}
174		if got := l.findInstrument("M-NEW"); got == nil ||
175			got.RegisteredAt != "2026-10-05T00:00:00Z" ||
176			got.Name != "成功名称" || got.AllowedError != 0.75 {
177			t.Fatalf("台账内的新器具应采用本次成功提交的内容：%+v", got)
178		}
179	
180		// 成功后再次登记同号仍按现有规则拒绝；原有器具与记录仍保持原样。
181		if _, err := l.Register(failed); !IsValidation(err) ||
182			!strings.Contains(err.Error(), "已存在") {
183			t.Fatalf("成功登记后同号应按编号唯一拒绝：%v", err)
184		}
185		if len(l.Instruments()) != 3 {
186			t.Fatalf("重复登记不应新增器具：%+v", l.data.Instruments)
187		}
188		if got := l.findInstrument("M-1"); got.Status != StatusRetired {
189			t.Fatalf("原有器具状态被改动：%+v", got)
190		}
191		if l.findPlan("P-1") == nil || l.findCertificate("C-1") == nil {
192			t.Fatal("原有证书或计划丢失")
193		}
194	
195		// 重开文件：磁盘上只有 M-1、M-2、M-NEW（本次成功内容），不含失败申请。
196		reopened, err = openAt(path, clock.now)
197		if err != nil {
198			t.Fatalf("reopen: %v", err)
199		}
200		if len(reopened.data.Instruments) != 3 {
201			t.Fatalf("重开后应有三件器具：%+v", reopened.data.Instruments)
202		}
203		got := reopened.findInstrument("M-NEW")
204		if got == nil || got.Name != "成功名称" || got.AllowedError != 0.75 ||
205			got.RegisteredAt != "2026-10-05T00:00:00Z" || got.Status != StatusPending {
206			t.Fatalf("文件中的新器具内容异常：%+v", got)
207		}
208		raw, err = os.ReadFile(path)
209		if err != nil {
210			t.Fatalf("读取台账文件: %v", err)
211		}
212		if strings.Contains(string(raw), "失败名称") {
213			t.Fatalf("失败申请的内容最终仍被写入文件：\n%s", raw)
214		}
215	}
216	
217	// TestFailedRegisterOnBrandNewLedgerLeavesEmptyLedger 覆盖首次登记新台账时
218	// 写盘失败的情形：失败后台账仍是空台账，查询列表为空、按编号核对报不存在；
219	// 恢复后重新提交才创建文件并新增器具。
220	func TestFailedRegisterOnBrandNewLedgerLeavesEmptyLedger(t *testing.T) {
221		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
222		path := filepath.Join(t.TempDir(), "ledger.json")
223		l, err := openAt(path, clock.now)
224		if err != nil {
225			t.Fatalf("open: %v", err)
226		}
227	
228		// 新台账尚无文件：直接用同名目录挡住原子替换（无需先移除台账文件）。
229		if err := os.Mkdir(path, 0o755); err != nil {
230			t.Fatalf("以同名目录挡住台账创建: %v", err)
231		}
232		in := RegisterInput{ID: "M-1", Name: "万用表", AllowedError: 0.5}
233		if got, err := l.Register(in); err == nil || got != nil {
234			t.Fatalf("首次登记写盘失败应返回保存错误：err=%v inst=%v", err, got)
235		} else if IsValidation(err) || !strings.Contains(err.Error(), path) {
236			t.Fatalf("应为指出台账路径的保存错误：%v", err)
237		}
238	
239		// 失败后继续查询同一台账：与登记前一致——空列表、编号不存在。
240		if listed := l.Instruments(); len(listed) != 0 {
241			t.Fatalf("失败后列表应为空：%+v", listed)
242		}
243		if _, err := l.Review("M-1"); !errors.Is(err, ErrNotFound) {
244			t.Fatalf("失败编号核对应报不存在：%v", err)
245		}
246		if _, err := l.RequestUse("M-1"); !errors.Is(err, ErrNotFound) {
247			t.Fatalf("失败编号不能申请使用：%v", err)
248		}
249		// 文件仍不可写时再次提交合法内容继续报保存错误，不能变成编号重复。
250		if _, err := l.Register(in); IsValidation(err) {
251			t.Fatalf("再次提交不得被当成编号重复：%v", err)
252		}
253		// 不合法内容仍按业务校验拒绝。
254		if _, err := l.Register(RegisterInput{ID: " ", Name: "x", AllowedError: 1}); !IsValidation(err) {
255			t.Fatalf("空白编号应报业务校验错误：%v", err)
256		}
257	
258		// 恢复可写：无需重开，时钟前进后重新提交才真正创建台账文件。
259		restoreSaving(t, l)
260		clock.t = mustDate(t, "2026-10-05")
261		ok, err := l.Register(RegisterInput{ID: "M-1", Name: "万用表", AllowedError: 0})
262		if err != nil || ok == nil {
263			t.Fatalf("恢复后零误差登记应成功：err=%v inst=%v", err, ok)
264		}
265		if ok.RegisteredAt != "2026-10-05T00:00:00Z" || ok.AllowedError != 0 ||
266			ok.Status != StatusPending {
267			t.Fatalf("成功登记内容异常：%+v", ok)
268		}
269		reopened, err := openAt(path, clock.now)
270		if err != nil {
271			t.Fatalf("reopen: %v", err)
272		}
273		if len(reopened.data.Instruments) != 1 || reopened.findInstrument("M-1") == nil {
274			t.Fatalf("文件中应有一件成功登记的器具：%+v", reopened.data.Instruments)
275		}
276	}
