202			if !r.CanUse || r.Instrument.Status != StatusInUse {
203				t.Fatalf("核对应仍显示在用且可以使用：%+v", r.Instrument)
204			}
205		}
206	
207		// 恢复后重新提交停用：保存成功才真正受限。
208		restoreSaving(t, l)
209		if err := l.SetStatus("M-1", StatusRetired); err != nil {
210			t.Fatalf("恢复后停用应成功: %v", err)
211		}
212		d, _ := l.CanUse("M-1")
213		if d.Allowed || !containsReason(d.Reasons, "停用") {
214			t.Fatalf("成功停用后应按停用限制使用：%v", d.Reasons)
215		}
216	}
217	
218	// TestFailedStatusSwitchKeepsCertificateBasedRestrictions 验证证书本身到期、
219	// 超差或缺失导致的使用限制，在状态切换保存失败时仍按既有规则判断。
220	func TestFailedStatusSwitchKeepsCertificateBasedRestrictions(t *testing.T) {
221		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
222	
223		// 在用 + 到期证书：切换停用失败后仍因到期被拒，原因里不能出现停用。
224		lExp := newTestLedger(t, clock)
225		mustRegister(t, lExp, "M-EXP", "万用表", 0.5)
226		mustAddCert(t, lExp, CertificateInput{
227			InstrumentID: "M-EXP", Number: "C-OLD", CalDate: "2025-01-01",
228			Expiry: "2025-12-31", Method: "m", Error: 0.1, Summary: "s",
229		})
230		if err := lExp.SetStatus("M-EXP", StatusInUse); err != nil {
231			t.Fatalf("set in-use: %v", err)
232		}
233		blockSaving(t, lExp)
234		if err := lExp.SetStatus("M-EXP", StatusRetired); err == nil {
235			t.Fatal("写盘失败应返回保存错误")
236		}
237		d, _ := lExp.CanUse("M-EXP")
238		if d.Allowed || !containsReason(d.Reasons, "到期") || containsReason(d.Reasons, "停用") {
239			t.Fatalf("失败停用不得替换证书到期原因：allowed=%v reasons=%v", d.Allowed, d.Reasons)
240		}
241	
242		// 在用 + 无证书：切换待校准失败后仍只因无证书被拒，不能出现待校准原因。
243		lNone := newTestLedger(t, clock)
244		mustRegister(t, lNone, "M-NONE", "万用表", 0.5)
245		if err := lNone.SetStatus("M-NONE", StatusInUse); err != nil {
246			t.Fatalf("set in-use: %v", err)
247		}
248		blockSaving(t, lNone)
249		if err := lNone.SetStatus("M-NONE", StatusPending); err == nil {
250			t.Fatal("写盘失败应返回保存错误")
251		}
252		d, _ = lNone.CanUse("M-NONE")
253		if d.Allowed || !containsReason(d.Reasons, "没有校准证书") ||
254			containsReason(d.Reasons, "待校准") {
255			t.Fatalf("失败的待校准切换不得增加状态原因：allowed=%v reasons=%v", d.Allowed, d.Reasons)
256		}
257	}
