525			Expiry: "2027-01-01", Method: "m", Error: 0, Summary: "s",
526		})
527		_, _, _ = l.AddCertificate(CertificateInput{
528			InstrumentID: "M-1", Number: "C-X", CalDate: "2026-01-01",
529			Expiry: "2026-01-01", Method: "m", Error: 0, Summary: "s",
530		})
531		_, _ = l.RequestUse("GHOST")
532	
533		reopened, err := openAt(path, clock.now)
534		if err != nil {
535			t.Fatalf("reopen: %v", err)
536		}
537		if len(reopened.Instruments()) != 1 {
538			t.Fatalf("重开后器具数量异常：%d", len(reopened.Instruments()))
539		}
540		if len(reopened.data.Certificates) != 0 || len(reopened.data.Usage) != 0 {
541			t.Fatalf("重开后发现半份记录：证书 %d 使用 %d",
542				len(reopened.data.Certificates), len(reopened.data.Usage))
543		}
544	}
545	
546	func mustRegister(t *testing.T, l *Ledger, id, name string, allowed float64) {
547		t.Helper()
548		if _, err := l.Register(RegisterInput{ID: id, Name: name, AllowedError: allowed}); err != nil {
549			t.Fatalf("register %s: %v", id, err)
550		}
551	}
552	
553	func mustAddCert(t *testing.T, l *Ledger, in CertificateInput) {
554		t.Helper()
555		if _, _, err := l.AddCertificate(in); err != nil {
556			t.Fatalf("add cert %s: %v", in.Number, err)
557		}
558	}
559	
560	func containsReason(reasons []string, sub string) bool {
561		for _, r := range reasons {
562			if strings.Contains(r, sub) {
563				return true
564			}
565		}
566		return false
567	}
568	
569	func sameReasons(a, b []string) bool {
570		if len(a) != len(b) {
571			return false
572		}
573		for i := range a {
574			if a[i] != b[i] {
575				return false
576			}
577		}
578		return true
579	}
