1	// Command ledger 是本地器具校准台账的命令行入口。
2	//
3	// 用法：
4	//
5	//	ledger -f 台账文件.json <子命令> [参数]
6	//
7	// 数据只保存在 -f 指定的本机文件中；不指定时使用当前目录下的 ledger.json。
8	// 不同文件是互不混入的不同台账，退出后再次打开同一文件可继续查询和操作。
9	package main
10	
11	import (
12		"encoding/json"
13		"errors"
14		"flag"
15		"fmt"
16		"io"
17		"math"
18		"os"
19		"strconv"
20		"strings"
21	
22		"github.com/bengzyyys/calibration-ledger/calibrate"
23	)
24	
25	const usageText = `本地器具校准台账（仅本机，不连接真实实验室）
26	
27	用法：
28	  ledger -f <台账文件> [--json] <子命令> [参数]
29	
30	子命令：
31	  register   登记器具：--id 编号 --name 名称 --allowed 允许绝对误差
32	  status     切换状态：--id 编号 --status 在用|停用|待校准
33	  cert       录入证书：--instrument 器具编号 --number 证书编号 \
34	             --cal-date YYYY-MM-DD --expiry YYYY-MM-DD \
35	             --method 方法 --error 测得误差 --summary 摘要
36	  use        申请使用器具：--id 编号（允许与拒绝都会留痕）
37	  review     按器具核对：--id 编号
38	  list       列出全部登记器具
39	  plan       建立校准计划：--instrument 器具编号 --number 计划编号 \
40	             --date YYYY-MM-DD --note 非空说明
41	  reschedule 计划改期：--number 计划编号 --date 新日期 --reason 非空原因
42	  cancel     取消计划：--number 计划编号 --reason 非空原因
43	  complete   用证书完成计划：--number 计划编号 --certificate 证书编号
44	  todos      校准待办：[--instrument 器具编号]（默认全部未结束计划）
45	
46	通用参数：
47	  -f, --file   台账文件路径（默认 ledger.json）
48	      --json   以 JSON 输出结果
49	
50	退出码：0 成功；1 业务拒绝或未找到；2 参数或读写错误。
51	`
52	
53	// options 是所有子命令共用的全局参数。
54	type options struct {
55		file   string
56		asJSON bool
57	}
58	
59	func main() {
60		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
61	}
62	
63	func run(args []string, stdout, stderr io.Writer) int {
64		if len(args) == 0 {
65			fmt.Fprint(stderr, usageText)
66			return 2
67		}
68		var opts options
69		fileSet := false
70		cmd := ""
71		businessArgs := make([]string, 0, len(args))
72		// 全局参数（-f/--file、--json）既可以写在子命令前，也可以与器具编号、
73		// 证书编号等业务参数交错写在子命令之后。这里先从左到右扫描整条命令行，
74		// 剥除全局参数并确定最终台账路径，再打开该文件：因此 -f 出现的位置不会
75		// 改变它选中的台账；同一次调用出现多个文件参数时，短名与长名共同参与
76		// 从左到右的顺序，以最后一次明确给出的路径为准。
77		// 子命令的业务标志（--method、--summary 等）都需要值：不带等号时紧跟的
78		// 下一个参数就是它的值。值必须原样保留为字段内容——即使它看起来是
79		// -f、--file=…、-f… 或 --json，也不参与台账选择与输出格式设置；
80		// 只有出现在完整字段之外（或子命令之前）的同名写法才是全局参数。
81		for i := 0; i < len(args); i++ {
82			a := args[i]
83			if cmd == "" && !strings.HasPrefix(a, "-") {
84				// 第一个不以“-”开头的参数是子命令；其后的位置参数仍要继续扫描。
85				cmd = a
86				continue
87			}
88			switch {
89			case a == "-f" || a == "--file" || a == "-file":
90				if i+1 >= len(args) {
91					fmt.Fprintf(stderr, "%s 需要一个值\n", a)
92					return 2
93				}
94				i++
95				opts.file = args[i]
96				fileSet = true
97			case strings.HasPrefix(a, "--file="):
98				opts.file = a[len("--file="):]
99				fileSet = true
100			case strings.HasPrefix(a, "-file="):
101				opts.file = a[len("-file="):]
102				fileSet = true
103			case strings.HasPrefix(a, "-f="):
104				opts.file = strings.TrimPrefix(a, "-f=")
105				fileSet = true
106			case strings.HasPrefix(a, "-f") && len(a) > 2:
107				opts.file = a[2:]
108				fileSet = true
109			case a == "--json" || a == "-json":
110				opts.asJSON = true
111			case a == "--" && cmd != "":
112				// “--” 终止后续标志解析：其后的参数原样交给子命令
113				// （与 flag 包的行为一致），即使其中出现 -f 也不再视为全局参数。
114				// 只有独立出现的 -- 才走这里；紧跟在需要值的业务标志之后时，它已在
115				// 下方默认分支被当作该标志的值，与 flag 包的取值规则保持一致。
116				businessArgs = append(businessArgs, args[i:]...)
117				i = len(args)
118			default:
119				if cmd == "" {
120					fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
121					return 2
122				}
123				businessArgs = append(businessArgs, a)
124				// 业务标志不带等号时，下一个参数是它的字段值：原样一并转交子命令，
125				// 绝不再按全局参数解释（与 flag 包对字符串标志的取值行为一致）。
126				// 值缺失时不在这里补，由子命令解析时报“标志需要值”。
127				if strings.HasPrefix(a, "-") && !strings.Contains(a, "=") && i+1 < len(args) {
128					i++
129					businessArgs = append(businessArgs, args[i])
130				}
131			}
132		}
133		if fileSet {
134			if strings.TrimSpace(opts.file) == "" {
135				fmt.Fprintln(stderr, "台账文件路径不能为空或只有空白")
136				return 2
137			}
138		} else {
139			opts.file = "ledger.json"
140		}
141		if cmd == "" {
142			fmt.Fprint(stderr, usageText)
143			return 2
144		}
145		cmdArgs := businessArgs
146		if cmd == "help" || cmd == "-h" || cmd == "--help" {
147			fmt.Fprint(stdout, usageText)
148			return 0
149		}
150	
151		// 最终路径确定之后才打开台账：被后续 -f 覆盖掉的旧路径与默认文件
152		// 即使损坏或不可读，也不会影响对有效目标文件的操作。
153		l, err := calibrate.Open(opts.file)
154		if err != nil {
155			fmt.Fprintln(stderr, "打开台账失败：", err)
156			return 2
157		}
158	
159		switch cmd {
160		case "register":
161			return cmdRegister(l, cmdArgs, opts, stdout, stderr)
162		case "status":
163			return cmdStatus(l, cmdArgs, opts, stdout, stderr)
164		case "cert":
165			return cmdCert(l, cmdArgs, opts, stdout, stderr)
166		case "use":
167			return cmdUse(l, cmdArgs, opts, stdout, stderr)
168		case "review":
169			return cmdReview(l, cmdArgs, opts, stdout, stderr)
170		case "list":
171			return cmdList(l, cmdArgs, opts, stdout, stderr)
172		case "plan":
173			return cmdPlan(l, cmdArgs, opts, stdout, stderr)
174		case "reschedule":
175			return cmdReschedule(l, cmdArgs, opts, stdout, stderr)
176		case "cancel":
177			return cmdCancel(l, cmdArgs, opts, stdout, stderr)
178		case "complete":
179			return cmdComplete(l, cmdArgs, opts, stdout, stderr)
180		case "todos":
181			return cmdTodos(l, cmdArgs, opts, stdout, stderr)
182		default:
183			fmt.Fprintf(stderr, "未知子命令 %q\n\n%s", cmd, usageText)
184			return 2
185		}
186	}
187	
188	// newFlagSet 构造子命令自己的标志集。台账文件与 --json 已在打开台账前
189	// 从整条命令行统一解析，这里只保留 --json 的登记，绝不在此处重新登记
190	// -f/--file：否则子命令后的文件参数会指向与已打开台账不同的路径。
191	func newFlagSet(name string, opts *options) *flag.FlagSet {
192		fs := flag.NewFlagSet(name, flag.ContinueOnError)
193		fs.SetOutput(io.Discard)
194		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
195		return fs
196	}
197	
198	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
199		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
200		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
201			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
202			return 0, false
203		}
204		return v, true
205	}
206	
207	func emit(opts options, stdout, stderr io.Writer, human string, v any) int {
208		if opts.asJSON {
209			raw, err := json.MarshalIndent(v, "", "  ")
210			if err != nil {
211				fmt.Fprintln(stderr, "输出 JSON 失败：", err)
212				return 2
213			}
214			fmt.Fprintln(stdout, string(raw))
215			return 0
216		}
217		fmt.Fprint(stdout, human)
218		return 0
219	}
220	
221	// failBusiness 处理业务拒绝：退出码 1，原记录未被改动。
222	func failBusiness(opts options, stdout, stderr io.Writer, err error, rejected any) int {
223		if opts.asJSON {
224			raw, _ := json.MarshalIndent(rejected, "", "  ")
225			fmt.Fprintln(stdout, string(raw))
226		}
227		fmt.Fprintln(stderr, "已拒绝：", err)
228		return 1
229	}
230	
231	func failIO(stderr io.Writer, err error) int {
232		fmt.Fprintln(stderr, "操作失败：", err)
233		return 2
234	}
235	
236	func cmdRegister(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
237		fs := newFlagSet("register", &opts)
238		id := fs.String("id", "", "器具唯一编号")
239		name := fs.String("name", "", "器具名称")
240		allowed := fs.String("allowed", "", "允许的绝对误差（不小于零的有限数）")
241		if err := fs.Parse(args); err != nil {
242			fmt.Fprintln(stderr, "register 参数错误：", err)
243			return 2
244		}
245		if *id == "" || *name == "" || *allowed == "" {
246			fmt.Fprintln(stderr, "register 必须提供 --id、--name、--allowed")
247			return 2
248		}
249		allowedErr, ok := parseFloat(stderr, *allowed, "允许的绝对误差")
250		if !ok {
251			return 2
252		}
253		inst, err := l.Register(calibrate.RegisterInput{
254			ID: *id, Name: *name, AllowedError: allowedErr,
255		})
256		if err != nil {
257			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
258				return failBusiness(opts, stdout, stderr, err,
259					map[string]any{"accepted": false, "error": err.Error()})
260			}
261			return failIO(stderr, err)
262		}
263		human := fmt.Sprintf("已登记器具 %s（%s），允许绝对误差 %g，状态：%s\n",
264			inst.ID, inst.Name, inst.AllowedError, inst.Status)
265		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "instrument": inst})
266	}
267	
268	func cmdStatus(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
269		fs := newFlagSet("status", &opts)
270		id := fs.String("id", "", "器具编号")
271		status := fs.String("status", "", "在用|停用|待校准")
272		if err := fs.Parse(args); err != nil {
273			fmt.Fprintln(stderr, "status 参数错误：", err)
274			return 2
275		}
276		if *id == "" || *status == "" {
277			fmt.Fprintln(stderr, "status 必须提供 --id、--status")
278			return 2
279		}
280		st, err := calibrate.ParseStatus(*status)
281		if err != nil {
282			fmt.Fprintln(stderr, err)
283			return 2
284		}
285		if err := l.SetStatus(*id, st); err != nil {
286			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
287				return failBusiness(opts, stdout, stderr, err,
288					map[string]any{"accepted": false, "error": err.Error()})
289			}
290			return failIO(stderr, err)
291		}
292		human := fmt.Sprintf("器具 %s 已切换为%s\n", *id, st)
293		return emit(opts, stdout, stderr, human,
294			map[string]any{"accepted": true, "id": *id, "status": st})
295	}
296	
297	func cmdCert(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
298		fs := newFlagSet("cert", &opts)
299		instrument := fs.String("instrument", "", "器具编号")
300		number := fs.String("number", "", "证书编号（全台账唯一）")
301		calDate := fs.String("cal-date", "", "校准日期 YYYY-MM-DD")
302		expiry := fs.String("expiry", "", "有效期截止日 YYYY-MM-DD")
303		method := fs.String("method", "", "校准方法")
304		measured := fs.String("error", "", "测得误差（有限数）")
305		summary := fs.String("summary", "", "证书摘要")
306		if err := fs.Parse(args); err != nil {
307			fmt.Fprintln(stderr, "cert 参数错误：", err)
308			return 2
309		}
310		// 证书录入只接受已有选项及其对应值：凡是独立传入、没有被任何选项作为值
311		// 接收的内容（无论夹在证书字段之间、放在末尾，还是位于“--”之后），都必须
312		// 让整次录入失败，不能默默丢掉一部分内容形成正式证书。flag 包会把这些内容
313		// 留在 Args 中（“--”本身被剥除，其后的参数原样保留）。检查放在任何业务
314		// 处理之前：即使字段已填齐、编号与已有证书同号同内容，也不允许录入或走
315		// 幂等返回，失败编号与该器具当天的证书位置都不会被占用。
316		if extra := fs.Args(); len(extra) > 0 {
317			quoted := make([]string, len(extra))
318			for i, a := range extra {
319				quoted[i] = strconv.Quote(a)
320			}
321			fmt.Fprintf(stderr,
322				"cert 参数错误：存在多余参数，证书录入只接受已有选项及其值，未被任何选项接收的内容：%s\n",
323				strings.Join(quoted, "、"))
324			return 2
325		}
326		missing := []string{}
327		for k, v := range map[string]string{
328			"--instrument": *instrument, "--number": *number, "--cal-date": *calDate,
329			"--expiry": *expiry, "--method": *method, "--error": *measured, "--summary": *summary,
330		} {
331			if strings.TrimSpace(v) == "" {
332				missing = append(missing, k)
333			}
334		}
335		if len(missing) > 0 {
336			fmt.Fprintln(stderr, "cert 缺少必填参数：", strings.Join(missing, "、"))
337			return 2
338		}
339		measuredErr, ok := parseFloat(stderr, *measured, "测得误差")
340		if !ok {
341			return 2
342		}
343		cert, duplicate, err := l.AddCertificate(calibrate.CertificateInput{
344			InstrumentID: *instrument,
345			Number:       *number,
346			CalDate:      *calDate,
347			Expiry:       *expiry,
348			Method:       *method,
349			Error:        measuredErr,
350			Summary:      *summary,
351		})
352		if err != nil {
353			if calibrate.IsValidation(err) || calibrate.IsConflict(err) || errors.Is(err, calibrate.ErrNotFound) {
354				return failBusiness(opts, stdout, stderr, err,
355					map[string]any{"accepted": false, "conflict": calibrate.IsConflict(err), "error": err.Error()})
356			}
357			return failIO(stderr, err)
358		}
359		note := "已录入新证书"
360		if duplicate {
361			note = "同号证书且内容一致，返回原证书，未增加历史记录"
362		}
363		// 证书结论只依赖本次证书自身的测得误差与所属器具登记的允许误差，
364		// 与录入反馈、最近证书、历史证书共用同一条规则（Certificate.Pass）；
365		// 不组装包含历史证书、使用拒绝记录与校准计划的完整核对结果。
366		inst, err := l.Instrument(cert.InstrumentID)
367		if err != nil {
368			return failIO(stderr, err)
369		}
370		verdict := "合格"
371		if !cert.Pass(inst.AllowedError) {
372			verdict = "超差"
373		}
374		human := fmt.Sprintf("%s：%s（器具 %s，校准日期 %s，截止日 %s，测得误差 %g，判定：%s）\n",
375			note, cert.Number, cert.InstrumentID, cert.CalDate, cert.Expiry, cert.Error, verdict)
376		return emit(opts, stdout, stderr, human,
377			map[string]any{"accepted": true, "duplicate": duplicate, "verdict": verdict, "certificate": cert})
378	}
379	
380	func cmdUse(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
381		fs := newFlagSet("use", &opts)
382		id := fs.String("id", "", "器具编号")
383		if err := fs.Parse(args); err != nil {
384			fmt.Fprintln(stderr, "use 参数错误：", err)
385			return 2
386		}
387		if strings.TrimSpace(*id) == "" {
388			fmt.Fprintln(stderr, "use 必须提供 --id")
389			return 2
390		}
391		d, err := l.RequestUse(*id)
392		if err != nil {
393			if errors.Is(err, calibrate.ErrNotFound) || calibrate.IsValidation(err) {
394				return failBusiness(opts, stdout, stderr, err,
395					map[string]any{"accepted": false, "recorded": false, "error": err.Error()})
396			}
397			return failIO(stderr, err)
398		}
399		if !d.Allowed {
400			var sb strings.Builder
401			sb.WriteString(fmt.Sprintf("拒绝使用器具 %s，已记录本次拒绝及原因：\n", *id))
402			for _, r := range d.Reasons {
403				sb.WriteString("  - " + r + "\n")
404			}
405			if opts.asJSON {
406				raw, _ := json.MarshalIndent(map[string]any{
407					"allowed": false, "recorded": true, "decision": d,
408				}, "", "  ")
409				fmt.Fprintln(stdout, string(raw))
410			}
411			fmt.Fprint(stderr, sb.String())
412			return 1
413		}
414		human := fmt.Sprintf("允许使用器具 %s，已记录本次申请。\n", *id)
415		return emit(opts, stdout, stderr, human,
416			map[string]any{"allowed": true, "recorded": true, "decision": d})
417	}
