419	func cmdReview(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
420		fs := newFlagSet("review", &opts)
421		id := fs.String("id", "", "器具编号")
422		if err := fs.Parse(args); err != nil {
423			fmt.Fprintln(stderr, "review 参数错误：", err)
424			return 2
425		}
426		if strings.TrimSpace(*id) == "" {
427			fmt.Fprintln(stderr, "review 必须提供 --id")
428			return 2
429		}
430		r, err := l.Review(*id)
431		if err != nil {
432			if errors.Is(err, calibrate.ErrNotFound) {
433				return failBusiness(opts, stdout, stderr, err,
434					map[string]any{"found": false, "error": err.Error()})
435			}
436			return failIO(stderr, err)
437		}
438		var sb strings.Builder
439		fmt.Fprintf(&sb, "器具 %s（%s）\n", r.Instrument.ID, r.Instrument.Name)
440		fmt.Fprintf(&sb, "  允许绝对误差：%g；当前状态：%s\n", r.Instrument.AllowedError, r.Instrument.Status)
441		if r.CanUse {
442			sb.WriteString("  当前能否使用：可以\n")
443		} else {
444			sb.WriteString("  当前能否使用：不可以，原因：\n")
445			for _, reason := range r.Reasons {
446				sb.WriteString("    - " + reason + "\n")
447			}
448		}
449		if r.Latest == nil {
450			sb.WriteString("  最近证书：无\n")
451		} else {
452			fmt.Fprintf(&sb, "  最近证书：%s（校准日期 %s，截止日 %s，判定：%s，%s）\n",
453				r.Latest.Number, r.Latest.CalDate, r.Latest.Expiry,
454				verdictText(r.Latest.Pass), expiryText(r.Latest.Expired))
455		}
456		if len(r.History) == 0 {
457			sb.WriteString("  历史证书：无\n")
458		} else {
459			sb.WriteString("  历史证书（按校准日期由近到远）：\n")
460			for _, c := range r.History {
461				fmt.Fprintf(&sb, "    - %s %s 截止 %s 误差 %g %s %s（%s）\n",
462					c.Number, c.CalDate, c.Expiry, c.Error,
463					verdictText(c.Pass), expiryText(c.Expired), c.Method)
464			}
465		}
466		if len(r.Rejections) == 0 {
467			sb.WriteString("  被拒绝的使用记录：无\n")
468		} else {
469			sb.WriteString("  被拒绝的使用记录（原因为申请当时冻结）：\n")
470			for _, u := range r.Rejections {
471				sb.WriteString("    - " + u.RequestedAt + "\n")
472				for _, reason := range u.Reasons {
473					sb.WriteString("        - " + reason + "\n")
474				}
475			}
476		}
477		if len(r.Plans) == 0 {
478			sb.WriteString("  校准计划：无\n")
479		} else {
480			sb.WriteString("  校准计划（含当前及已结束计划、改期记录与关联证书）：\n")
481			for _, p := range r.Plans {
482				head := fmt.Sprintf("    - %s %s 状态：%s", p.Number, p.PlannedDate, p.Status)
483				if p.Open() {
484					head += "（" + p.Marker + "）"
485				}
486				if p.OriginalDate != p.PlannedDate {
487					head += fmt.Sprintf("，最初计划日期 %s", p.OriginalDate)
488				}
489				head += "，说明：" + p.Note + "\n"
490				sb.WriteString(head)
491				for _, ch := range p.Changes {
492					fmt.Fprintf(&sb, "        改期 %s → %s（%s），原因：%s\n",
493						ch.From, ch.To, ch.ChangedAt, ch.Reason)
494				}
495				if p.Status == calibrate.PlanStatusCanceled {
496					fmt.Fprintf(&sb, "        取消于 %s，原因：%s\n", p.CanceledAt, p.CancelReason)
497				}
498				if p.Status == calibrate.PlanStatusDone {
499					fmt.Fprintf(&sb, "        完成于 %s，证书 %s\n", p.CompletedAt, p.CertificateNumber)
500				}
501			}
502		}
503		return emit(opts, stdout, stderr, sb.String(), r)
504	}
